'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { useEffect, useRef, useState } from 'react';

import { FeatherIcon, RotateCcwIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { TextLoader } from '@/registry/ndeko/ui/chat-loader';
import {
  Message,
  MessageAvatar,
  MessageContent,
  MessageGlyph,
} from '@/registry/ndeko/ui/chat-message';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import {
  Reasoning,
  ReasoningContent,
  ReasoningTrigger,
} from '@/registry/ndeko/ui/chat-reasoning';
import {
  ResponseStreamSegments,
  useTextStream,
} from '@/registry/ndeko/ui/chat-response-stream';
import {
  Tool,
  type ToolPart,
  type ToolState,
} from '@/registry/ndeko/ui/chat-tool';

import {
  answer,
  asker,
  finishedStep,
  question,
  reasoning,
  reasoningWordMs,
  runSchedule,
  thoughtLabel,
  toolCalls,
  type RunStep,
  type ToolCall,
} from './data';
import { rowPresenceOf } from './presence';
import { ReplySources } from './reply-sources';

function toolStateOf(tool: ToolCall, step: RunStep): ToolState {
  const isDone = step >= tool.doneAt;
  if (isDone) {
    return 'output-available';
  }
  return 'input-available';
}

function outputOf(tool: ToolCall, state: ToolState) {
  const isDone = state === 'output-available';
  if (isDone) {
    return tool.output;
  }
  return undefined;
}

function toolPartOf(tool: ToolCall, step: RunStep): ToolPart {
  const state = toolStateOf(tool, step);
  return {
    type: tool.type,
    state,
    input: tool.input,
    output: outputOf(tool, state),
    toolCallId: tool.toolCallId,
  };
}

function hasAppeared(tool: ToolCall, step: RunStep) {
  return step >= tool.appearsAt;
}

function ReasoningBody({
  isRunning,
  segments,
}: {
  isRunning: boolean;
  segments: ReturnType<typeof useTextStream>['segments'];
}) {
  if (isRunning) {
    return <ResponseStreamSegments segments={segments} />;
  }
  return reasoning;
}

function Reply03() {
  const [step, setStep] = useState<RunStep>(finishedStep);
  const [reasoningSource, setReasoningSource] = useState('');
  const timers = useRef(new Set<ReturnType<typeof setTimeout>>());
  const shouldReduceMotion = useReducedMotion();
  const rowPresence = rowPresenceOf(shouldReduceMotion);
  const isRunning = step < finishedStep;
  const isFinished = !isRunning;
  const visibleTools = toolCalls.filter((tool) => hasAppeared(tool, step));
  const reasoningStream = useTextStream({
    textStream: reasoningSource,
    mode: 'fade',
    segmentDelay: reasoningWordMs,
  });

  useEffect(() => {
    const pending = timers.current;
    return () => {
      pending.forEach((timer) => clearTimeout(timer));
    };
  }, []);

  function schedule(task: () => void, delay: number) {
    const timer = setTimeout(() => {
      timers.current.delete(timer);
      task();
    }, delay);
    timers.current.add(timer);
  }

  function runAgain() {
    if (isRunning) {
      return;
    }
    setStep(0);
    setReasoningSource(reasoning);
    reasoningStream.startStreaming();
    for (const entry of runSchedule) {
      schedule(() => setStep(entry.step), entry.atMs);
    }
  }

  return (
    <div className='bg-background text-foreground min-h-dvh w-full px-4 py-8 sm:px-6 sm:py-10'>
      <div className='mx-auto flex max-w-2xl flex-col gap-6'>
        <Message className='justify-end'>
          <MessageContent className='max-w-[85%] sm:max-w-[75%]'>
            {question}
          </MessageContent>
          <MessageAvatar
            src={asker.avatar}
            alt={asker.name}
            fallback={asker.initials}
            className='hidden sm:inline-flex'
          />
        </Message>

        <Message>
          <MessageGlyph>
            <FeatherIcon />
          </MessageGlyph>
          <div className='min-w-0 flex-1 space-y-3 pt-1.5'>
            <Reasoning isStreaming={isRunning}>
              <ReasoningTrigger>
                <Swap swapKey={String(isRunning)}>
                  {isRunning && <TextLoader text='Thinking' />}
                  {isFinished && thoughtLabel}
                </Swap>
              </ReasoningTrigger>
              <ReasoningContent>
                <ReasoningBody
                  isRunning={isRunning}
                  segments={reasoningStream.segments}
                />
              </ReasoningContent>
            </Reasoning>

            <ul aria-label='Tool calls' className='flex flex-col'>
              <AnimatePresence initial={false}>
                {visibleTools.map((tool) => (
                  <motion.li
                    key={tool.id}
                    className='-mx-1 overflow-hidden px-1'
                    {...rowPresence}
                  >
                    <div className='pb-2'>
                      <Tool toolPart={toolPartOf(tool, step)} />
                    </div>
                  </motion.li>
                ))}
              </AnimatePresence>
            </ul>

            <AnimatePresence initial={false}>
              {isFinished && (
                <motion.div
                  key='answer'
                  className='-mx-1 overflow-hidden px-1'
                  {...rowPresence}
                >
                  <div className='space-y-4 pb-1'>
                    <MessageContent markdown variant='plain'>
                      {answer}
                    </MessageContent>
                    <ReplySources />
                    <Button
                      type='button'
                      variant='ghost'
                      size='sm'
                      onClick={runAgain}
                      className='text-muted-foreground -ms-2'
                    >
                      <RotateCcwIcon />
                      Run again
                    </Button>
                  </div>
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        </Message>
      </div>
    </div>
  );
}

export default Reply03;

import {
  Source,
  SourceContent,
  SourceTrigger,
} from '@/registry/ndeko/ui/chat-source';

import { sources } from './data';

export function ReplySources() {
  return (
    <div className='space-y-2'>
      <p className='text-muted-foreground text-xs font-medium'>Sources</p>
      <ul className='flex flex-wrap gap-1.5'>
        {sources.map((source) => (
          <li key={source.href}>
            <Source href={source.href}>
              <SourceTrigger label={source.title} showMark />
              <SourceContent
                title={source.title}
                description={source.description}
              />
            </Source>
          </li>
        ))}
      </ul>
    </div>
  );
}

import type { MotionProps, Transition } from 'motion/react';

type PresenceProps = Pick<
  MotionProps,
  'initial' | 'animate' | 'exit' | 'transition'
>;

const EASE_OUT_STRONG: [number, number, number, number] = [0.23, 1, 0.32, 1];

const ENTER: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

const EXIT: Transition = { duration: 0.14, ease: EASE_OUT_STRONG };

const ROW_PRESENCE: PresenceProps = {
  initial: { height: 0, opacity: 0 },
  animate: { height: 'auto', opacity: 1 },
  exit: { height: 0, opacity: 0, transition: EXIT },
  transition: ENTER,
};

const FADE_PRESENCE: PresenceProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

export function rowPresenceOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return ROW_PRESENCE;
}

export type RunStep = 0 | 1 | 2 | 3 | 4 | 5;

export const finishedStep: RunStep = 5;

export type ScheduledStep = {
  step: RunStep;
  atMs: number;
};

export const runSchedule: ScheduledStep[] = [
  { step: 1, atMs: 500 },
  { step: 2, atMs: 1700 },
  { step: 3, atMs: 2000 },
  { step: 4, atMs: 3400 },
  { step: 5, atMs: 4000 },
];

export type ToolCall = {
  id: string;
  type: string;
  toolCallId: string;
  appearsAt: RunStep;
  doneAt: RunStep;
  input: Record<string, unknown>;
  output: Record<string, unknown>;
};

export type CitedSource = {
  href: string;
  title: string;
  description: string;
};

export const asker = {
  name: 'Jonas Weber',
  initials: 'JW',
  avatar: '/avatars/avatar-03.svg',
};

export const question =
  'Check the API reference against the changelog and tell me what changed in 2.4';

export const reasoning =
  'The API reference was last edited on 12 March, before 2.4 shipped, so it is probably behind. I will find the 2.4 entry in the changelog first, then read the parts of the API reference it touches: pagination, rate limits and the comment endpoints.';

export const thoughtLabel = 'Thought for 4 seconds';

export const answer = [
  'Three changes from 2.4 are missing from the API reference:',
  '',
  '1. **Pagination** on `/documents` moved from `page` to `cursor`.',
  '2. Workspace tokens now get 120 requests a minute instead of 60.',
  '3. `DELETE /comments/{id}` is new and not listed yet.',
  '',
  'The reference also still documents `archived=true` on `/spaces`, which 2.4 removed. I can draft the edits as suggestions on the page.',
].join('\n');

export const toolCalls: ToolCall[] = [
  {
    id: 'search',
    type: 'search_pages',
    toolCallId: 'call_7hq2',
    appearsAt: 1,
    doneAt: 2,
    input: { query: 'changelog 2.4', space: 'Engineering' },
    output: {
      matches: 3,
      best: 'Changelog / 2.4',
      updated: '2026-10-21',
    },
  },
  {
    id: 'read',
    type: 'read_page',
    toolCallId: 'call_9kd4',
    appearsAt: 3,
    doneAt: 4,
    input: { page: 'API reference', sections: ['Pagination', 'Rate limits'] },
    output: {
      words: 1240,
      lastEdited: '2026-03-12',
      endpoints: ['/documents', '/spaces', '/comments'],
    },
  },
];

export const sources: CitedSource[] = [
  {
    href: 'https://docs.quillstone.example/engineering/changelog#2-4',
    title: 'Changelog, 2.4',
    description:
      'Cursor pagination, higher limits for workspace tokens and comment deletion.',
  },
  {
    href: 'https://docs.quillstone.example/engineering/api-reference',
    title: 'API reference',
    description:
      'Endpoints, parameters and errors of the public API, last edited in March.',
  },
  {
    href: 'https://docs.quillstone.example/engineering/rate-limits',
    title: 'Rate limits',
    description:
      'How requests are counted per token and what happens past the limit.',
  },
];

export const reasoningWordMs = 55;
